package cmd

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"expense-reporter/internal/appender"
	"expense-reporter/internal/feedback"
	"expense-reporter/internal/parse"
)

// TestJoinID_SingleExpenseIDsAgree ensures that for a single (non-installment) expense,
// the ID generated by feedback.GenerateID matches the first entry ID predicted by
// appender.PredictEntryIDs. This prevents regression where different ID generation paths
// would produce mismatched IDs due to inconsistent date normalization.
func TestJoinID_SingleExpenseIDsAgree(t *testing.T) {
	// Use a bare date string "DD/MM" without year to ensure the year resolution logic is exercised.
	// If we used "DD/MM/YYYY", the raw and normalized strings would be identical,
	// which would silently disable this test instead of failing it.
	const (
		item     = "Posto Ipiranga"
		dateStr  = "15/04" // bare date without year
		valueStr = "35,50"
	)

	// Pin the clock deterministically to avoid dependency on runtime day.
	now := time.Date(2026, 7, 29, 0, 0, 0, 0, time.UTC)
	opts := parse.Options{
		Year:       2024, // Explicit year from flag — outranks config and clock
		ConfigYear: 2022,
		Now:        now,
	}

	pe, err := parse.Fields(item, dateStr, valueStr, opts)
	require.NoError(t, err)

	assert.Equal(t, 1, pe.Installments, "this test relies on a single expense (no installments)")

	// Generate the canonical date string from parsed expense
	canonicalDateStr := pe.DateString()

	// Compute ID using feedback path
	feedbackID := feedback.GenerateID(item, canonicalDateStr, pe.Value)

	// Predict IDs using appender path
	predictedIDs := appender.PredictEntryIDs(item, pe.Date, pe.Value, pe.Installments)

	assert.Len(t, predictedIDs, 1, "single expense should produce exactly one entry ID")
	assert.Equal(t, feedbackID, predictedIDs[0], "feedback and appender ID generation must agree for single expenses")
}

// TestJoinID_InstallmentSeriesDiverges documents that installment series legitimately
// produce different IDs between the feedback log and the expense log. This divergence
// is correct and deliberate: the feedback log records a single entry with the original item,
// while each installment gets its own row in the expense log with a suffixed item.
// This test ensures this behavior remains intentional and isn't accidentally "fixed".
func TestJoinID_InstallmentSeriesDiverges(t *testing.T) {
	// Parse an installment value to ensure we have a multi-installment case
	const (
		item     = "Compra de Eletrônicos"
		dateStr  = "10/03"    // bare date without year
		valueStr = "120,00/3" // total of 3 installments
	)

	// Pin the clock deterministically to avoid dependency on runtime day.
	now := time.Date(2026, 7, 29, 0, 0, 0, 0, time.UTC)
	opts := parse.Options{
		Year:       2024,
		ConfigYear: 2022,
		Now:        now,
	}

	pe, err := parse.Fields(item, dateStr, valueStr, opts)
	require.NoError(t, err)

	assert.Equal(t, 3, pe.Installments, "this test relies on a multi-installment expense")

	// Generate the canonical date string from parsed expense
	canonicalDateStr := pe.DateString()

	// Compute ID using feedback path (uses original item name)
	feedbackID := feedback.GenerateID(item, canonicalDateStr, pe.Value)

	// Predict IDs using appender path (first entry has suffixed item name)
	predictedIDs := appender.PredictEntryIDs(item, pe.Date, pe.Value, pe.Installments)

	assert.Len(t, predictedIDs, 3, "three installments should produce three entry IDs")
	assert.NotEqual(t, feedbackID, predictedIDs[0], "feedback and first installment ID must differ for multi-installment series")
}
